"""Migration of Meridian CRM 4.2 CRMScript division semantics."""


def _legacy_numeric(value) -> float:
    """Apply legacy numeric-context coercion for supported operand values."""
    if value is None:
        return 0.0
    if isinstance(value, str):
        if value.strip() == "":
            return 0.0
        return float(value)
    return float(value)


def safe_div(a, b) -> tuple[float, list[str]]:
    """
    Divide using legacy CRMScript semantics.

    A divisor that coerces to zero returns numeric zero and emits exactly one
    SCRIPT_DIV0 audit event rather than raising a division-by-zero exception.
    """
    dividend = _legacy_numeric(a)
    divisor = _legacy_numeric(b)

    if divisor == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    return dividend / divisor, []
